def evaluate(n, p_right, gamma, sweeps=500):
    V = [0.0] * n
    for _ in range(sweeps):
        for s in range(1, n - 1):
            right = reward(s + 1, n) + gamma * V[s + 1]
            left = reward(s - 1, n) + gamma * V[s - 1]
            V[s] = p_right * right + (1 - p_right) * left
    return V

