def reward(s2, n):
    if s2 == 0:
        return -1.0
    if s2 == n - 1:
        return 1.0
    return 0.0

def value_iteration(n, gamma, step_cost, sweeps=500):
    V = [0.0] * n
    def q(s, s2):
        return reward(s2, n) + step_cost + gamma * V[s2]
    for _ in range(sweeps):
        for s in range(1, n - 1):
            V[s] = max(q(s, s + 1), q(s, s - 1))
    policy = [None] * n
    for s in range(1, n - 1):
        policy[s] = 'R' if q(s, s + 1) >= q(s, s - 1) else 'L'
    return V, policy
